class Reader:
    def wanted(self,value,/,prefix='A',*,suffix='!'):
        return value.startswith(prefix) and value.endswith(suffix)
value=Reader();saved=value.wanted
print(saved('ABC!'),value.wanted('ABC!',suffix='?'))
Reader.wanted.__defaults__=('B',)
Reader.wanted.__kwdefaults__['suffix']='?'
print(saved('BCD?'),value.wanted('AX!',prefix='A',suffix='!'))
for bad in [lambda:saved(value='x'),lambda:saved('x',prefix='A',self=value),lambda:saved()]:
    try:bad()
    except TypeError:print('TypeError')

class Reader:
    def old(self,value): return value.lower()
    def new(self,value): return value.upper()
    read=old
value=Reader();saved=value.read
def argument():
    Reader.read=Reader.new
    return 'aB'
print(value.read(argument()),saved('Cd'),value.read('eF'))

class Reader:
    @classmethod
    def wanted(cls,value,*,prefix='A'): return value.startswith(prefix)
    @staticmethod
    def trim(value): return value.strip()
    def identity(self,value): return value
value=Reader();saved=Reader.wanted
print(Reader.wanted('ABC'),value.wanted('ABC',prefix='B'),saved('BCD',prefix='B'))
print(Reader.trim(' x '),value.trim(' y '),Reader.identity(value,'z'))

class Reader:
    def words(self,line): return line.lower().split()
class Descriptor:
    def __get__(self,instance,owner):return Reader().words
class Box:read=Descriptor()
print(Box().read('A B'))
class More:
    def __call__(self,value,*,prefix='A'):return value.startswith(prefix)
target=More();saved=target.__call__
print(target('AB'),saved('CD',prefix='C'))

prefix='A'
class Parent:
    def read(self,value):return value.lower()
class Child(Parent):
    def read(self,value):return super().read(value)
    def wanted(self,value):return value.startswith(prefix)
child=Child();saved=child.wanted
print(child.read('AB'),saved('AB'))
prefix='B'
print(saved('AB'),saved('BC'))
